"""Repositories over an in-memory Store, one class per persistence port.

CRUD, reads and filters run for real. Anything else raises
NotImplementedError with its work order — an aggregate or guard body
is specified by its pattern, not invented here.
"""

from typing import Any, Dict, List, Optional, Union

import datetime

import models
import errors
from store import Store, match_criterion


def _record_values(data, field_names):
    """A dataclass or dict entity argument as a `{field: value}` dict."""
    if data is None:
        return {}
    if isinstance(data, dict):
        return {name: data.get(name) for name in field_names}
    return {name: getattr(data, name, None) for name in field_names}



class CategoryRepository:
    ENTITY = "Category"
    PK = "id"

    def __init__(self, store):
        self._store = store


    def create(self, name: str = None, description: str = None, monthly_budget: int = None, icon: str = None) -> models.Category:
        """Creates a new category with the provided name, description, monthly budget (in cents), and icon. [crud:create: STANDARD_CRUD]"""
        values = {}
        if name is not None:
            values['name'] = name
        if description is not None:
            values['description'] = description
        if monthly_budget is not None:
            values['monthly_budget'] = monthly_budget
        if icon is not None:
            values['icon'] = icon
        unknown = [k for k in values if k not in ['id', 'name', 'description', 'monthly_budget', 'icon']]
        if unknown:
            raise ValueError(f"cannot create Category from {unknown}")
        for unique_field in ['name']:
            value = values.get(unique_field)
            if value is not None and self._store.select(self.ENTITY, [(unique_field, 'eq', value)]):
                raise ValueError(f"Category with {unique_field}={value!r} already exists")
        record = self._store.add(self.ENTITY, self.PK, values, check_fk=[])
        return models.Category(**record)

    def read_one(self, id: int = None) -> models.Category:
        """Retrieves a category by its ID. [crud:read_one: STANDARD_CRUD]"""
        record = self._store.get(self.ENTITY, self.PK, id, error=errors.CategoryNotFoundError)
        return models.Category(**record)

    def read_all(self) -> list[models.Category]:
        """Retrieves all categories. [crud:read_all: READ_ALL]"""
        criteria = []
        found = self._store.select(self.ENTITY, criteria)
        return [models.Category(**r) for r in found]

    def update(self, id: int = None, data: dict[str, any] = None) -> models.Category:
        """Updates a category's fields (name, description, monthly_budget, icon) by ID. [crud:update: STANDARD_CRUD]"""
        criteria = []
        if id is not None:
            criteria.append(('id', 'eq', id))
        found = self._store.select(self.ENTITY, criteria)
        if len(found) != 1:
            raise errors.CategoryNotFoundError(f"Category update matched {len(found)} records")
        patch = {}
        if id is not None and 'id' in ['id', 'name', 'description', 'monthly_budget', 'icon']:
            patch['id'] = id
        if data is not None and 'data' in ['id', 'name', 'description', 'monthly_budget', 'icon']:
            patch['data'] = data
        for unique_field in ['name']:
            value = patch.get(unique_field)
            if value is not None and any(row.get(self.PK) != found[0][self.PK] for row in self._store.select(self.ENTITY, [(unique_field, 'eq', value)])):
                raise ValueError(f"Category with {unique_field}={value!r} already exists")
        record = self._store.update(self.ENTITY, self.PK, found[0][self.PK], patch, error=errors.CategoryNotFoundError)
        return models.Category(**record)

    def delete(self, id: int = None) -> None:
        """Deletes a category by its ID. [crud:delete: STANDARD_CRUD]"""
        criteria = []
        if id is not None:
            criteria.append(('id', 'eq', id))
        found = self._store.select(self.ENTITY, criteria)
        if not found:
            raise errors.CategoryNotFoundError(f"Category delete matched no records")
        for record in found:
            self._store.delete(self.ENTITY, self.PK, record[self.PK])
        return None

    def find_expenses_by_category(self, category_id: int = None) -> list[models.Expense]:
        """Returns all expenses associated with a given category ID. [crud:filter: signature-pagination]"""
        criteria = []
        if category_id is not None:
            criteria.append(('category_id', 'eq', category_id))
        found = self._store.select('Expense', criteria)
        return [models.Expense(**r) for r in found]


