    def read_one(self, category_id: int = None, month: str = None) -> models.Budget:
        """Retrieves a budget by category ID and month. [crud:read_one: READ_ONE_BY_ID]"""
        criteria = []
        if category_id is not None:
            criteria.append(('category_id', 'eq', category_id))
        if month is not None:
            criteria.append(('month', 'eq', month))
        found = self._store.select(self.ENTITY, criteria)
        if len(found) != 1:
            raise errors.CategoryNotFoundError(f"Budget lookup matched {len(found)} records")
        record = found[0]
        return models.Budget(**record)

    def read_all(self, category_id: int = None, month: str = None) -> list[models.Budget]:
        """Retrieves all budgets for a given category (optional) or all budgets if no category is specified. [crud:read_all: signature-pagination]"""
        criteria = []
        if category_id is not None:
            criteria.append(('category_id', 'eq', category_id))
        if month is not None:
            criteria.append(('month', 'eq', month))
        found = self._store.select(self.ENTITY, criteria)
        return [models.Budget(**r) for r in found]

    def update(self, category_id: int = None, month: str = None, amount_limit_cents: int = None) -> models.Budget:
        """Updates the amount limit for a budget entry by category and month. [crud:read_one: gap NO_PATTERN_IN_DOMAIN: BUDGET_OVERFLOW_GUARD refused (BUDGET_OVERFLOW_GUARD returns boolean/none, but this method returns entity (Budget)); read-one by parameter shape]"""
        criteria = []
        if category_id is not None:
            criteria.append(('category_id', 'eq', category_id))
        if month is not None:
            criteria.append(('month', 'eq', month))
        if amount_limit_cents is not None:
            criteria.append(('amount_limit_cents', 'eq', amount_limit_cents))
        found = self._store.select(self.ENTITY, criteria)
        if len(found) != 1:
            raise errors.CategoryNotFoundError(f"Budget lookup matched {len(found)} records")
        record = found[0]
        return models.Budget(**record)

    def delete(self, category_id: int = None, month: str = None) -> None:
        """Deletes a budget entry by category and month. [crud:delete: STANDARD_CRUD]"""
        criteria = []
        if category_id is not None:
            criteria.append(('category_id', 'eq', category_id))
        if month is not None:
            criteria.append(('month', 'eq', month))
        found = self._store.select(self.ENTITY, criteria)
        if not found:
            raise errors.CategoryNotFoundError(f"Budget delete matched no records")
        for record in found:
            self._store.delete(self.ENTITY, self.PK, record[self.PK])
        return None

    def check_budget_exceeded(self, category_id: int = None, month: str = None) -> bool:
        """Checks whether a category's budget has been exceeded for a given month based on existing expenses. [BUDGET_OVERFLOW_GUARD via answered slots: limit_field=amount_limit_cents, target_field=amount_cents, date_field=expense_date, spend_entity=Expense]"""
        if not (month):
            raise ValueError("budget check needs a month scope: an empty month matches every record")
        budgets = self._store.select(self.ENTITY, [])
        match = [record for record in budgets
                    if record.get('category_id') == category_id
                    if record.get('month') == month
        ]
        if not match:
            return True  # no budget record: no limit to exceed
        limit = match[0].get('amount_limit_cents')
        spent = 0
        for record in self._store.select('Expense', []):
            if record.get('category_id') != category_id:
                continue
            if not str(record.get('expense_date') or '').startswith(month):
                continue
            spent += record.get('amount_cents') or 0
        return spent <= limit if limit is not None else True

def _call(bound, values, deps):
    action = bound[0]
    spec = ADAPTERS[action]
    service = deps['services'][_sanitize(spec['service'])]
    method = getattr(service, _sanitize(spec['method']))
    present = {_normalize(k): v for k, v in values.items()}
    argv = spec.get('argv', {})
    targets = spec.get('targets', {})
    assembled = set(spec.get('assembled', []))
    grouped = {}
    for field_name, (target_param, kind, required) in spec['fields']:
        if field_name in assembled:
            continue  # built from its sibling fields, not from argv
        dest = argv.get(field_name)
        given = present.get(_normalize(dest)) if dest is not None else None
        # An absent no-value flag parses as False: it was not given, so the
        # method's own default applies (`member list` without --active-only
        # lists everyone, not the inactive).
        if given is None or given is False:
            if required and given is None:
                raise ValueError(f"missing required field {field_name!r} for {action!r}")
            continue
        value = _transform(kind, given, field_name)
        if targets.get(target_param) is not None:
            grouped.setdefault(target_param, {})[field_name] = value
        else:
            grouped[target_param] = value
    call_kwargs = {}
    for target_param, value in grouped.items():
        model_name = targets.get(target_param)
        if model_name is not None and isinstance(value, dict):
            call_kwargs[_sanitize(target_param)] = getattr(models, model_name)(**value)
        else:
            call_kwargs[_sanitize(target_param)] = value
    return method(**call_kwargs)


def _sanitize(text):
    cleaned = "".join(c if c.isalnum() or c == "_" else "_" for c in str(text))
    cleaned = cleaned.strip("_") or "opt"
    return "_" + cleaned if cleaned[:1].isdigit() else cleaned


def build_cli(db_path=None):
    store = Store(db_path, SCHEMA)
    repos = {cls_name: getattr(repositories, cls_name)(store) for cls_name in REPOSITORIES}
    hired = {cls_name: getattr(services, cls_name)(repos) for cls_name in SERVICES}
    entities = {_normalize(name): getattr(models, name) for name in MODELS}
    return {'store': store, 'repos': repos,
            'services': {**repos, **hired},
            'entities': entities}


def _dispatch(binding, values, deps):
    """Run one click command against shared dependencies."""
    bound = BINDINGS.get(tuple(binding))
    if bound is None:
        raise click.ClickException(
            f"no adapter bound for {' '.join(binding)} — not implemented")
    choice, present = _choose(bound, values)
    trouble = _incomplete(choice, bound, present)
    if trouble:
        raise click.ClickException(
            f"{' '.join(binding)}: {trouble}")
    try:
        _show(_call(choice, values, deps))
    except click.ClickException:
        raise
    except Exception as error:
        raise click.ClickException(_error_text(error)) from error
    return 0


@click.group('x')
